service.method:

UPDATE SCODE
	SET
		  TEXT1		      = ${TEXT1}
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}	
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
	AND TYPE 		      = 'UX049'
	AND CODE              = ${CODE}
	AND LANGUAGE 		  = ${LANGUAGE}


INSERT INTO SCODE
	(
		  HOUSE_CODE
		, TYPE 
		, CODE
		, LANGUAGE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, USE_FLAG
		, TEXT1
		, DEL_FLAG
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, 'UX049'
		, ${CODE}
		, ${LANGUAGE}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, 'Y'
		, ${TEXT1}
		, 'N'
	)
